import test from "node:test";
import assert from "node:assert/strict";
import { liveView } from "../web/live.js";
import { rpc } from "../web/request.js";

// The follower has no LAN address: every request must still go to the current gateway.
test("live preview relays an ESP-NOW-only follower through the dashboard host", async () => {
	const original = { fetch: globalThis.fetch, document: globalThis.document, window: globalThis.window, location: globalThis.location };
	const calls = [], frames = [];
	globalThis.document = { readyState: "complete", hidden: false, addEventListener() {} };
	globalThis.window = { addEventListener() {} };
	globalThis.location = { origin: "http://192.168.1.106" };
	globalThis.fetch = async (url, options = {}) => {
		calls.push(url);
		assert.ok(url.startsWith(location.origin + "/inter_comms/"));
		assert.ok(options.signal);
		if (url.endsWith("/request")) return new Response(JSON.stringify({ id: "a".repeat(32) }));
		if (url.includes("/rpc?")) {
			assert.deepEqual(JSON.parse(options.body), { op: "live", target: "98a316a679fc" });
			return new Response(null, { status: 202 });
		}
		return new Response(JSON.stringify({ ok: true, leds: ["ffa000", "000000"] }));
	};
	const view = liveView((frame) => frames.push(frame));
	try {
		view.select({ id: "98a316a679fc", ip: "", liveRelay: true }, "98a316a678ac");
		await new Promise((resolve) => setTimeout(resolve, 280));
		assert.ok(calls.length >= 3);
		assert.ok(frames.some((frame) => Array.isArray(frame) && frame[0] === "ffa000"));
	} finally {
		view.setVisible(false);
		Object.assign(globalThis, original);
	}
});

// Cancel a network read that never returns; changing preview targets must not strand the RPC.
test("dashboard RPC cancellation aborts an outstanding fetch", async () => {
	const original = globalThis.fetch;
	globalThis.fetch = (_, { signal }) => new Promise((_, reject) => {
		if (signal.aborted) reject(new DOMException("Aborted", "AbortError"));
		else signal.addEventListener("abort", () => reject(new DOMException("Aborted", "AbortError")), { once: true });
	});
	try {
		const controller = new AbortController();
		const request = rpc("http://gateway", { op: "status" }, { signal: controller.signal });
		controller.abort();
		await assert.rejects(request, { name: "AbortError" });
	} finally { globalThis.fetch = original; }
});

// The deadline covers reservation and POST, rather than starting only after both have returned.
test("dashboard RPC times out even when request reservation hangs", async (context) => {
	context.mock.timers.enable({ apis: ["setTimeout"] });
	const original = globalThis.fetch;
	globalThis.fetch = (_, { signal }) => new Promise((_, reject) => {
		signal.addEventListener("abort", () => reject(new DOMException("Aborted", "AbortError")), { once: true });
	});
	try {
		const request = rpc("http://gateway", { op: "status" });
		context.mock.timers.tick(12000);
		await assert.rejects(request, { name: "AbortError" });
	} finally { globalThis.fetch = original; }
});
